using System;
using System.Linq;
using Mono.Cecil;
using Mono.Cecil.Cil;

class P {
  static void Main(string[] a) {
    var asm = AssemblyDefinition.ReadAssembly(a[0]);
    var mw = asm.MainModule.Types.First(x => x.FullName == "SourceTree.MainWindow");
    var m = mw.Methods.First(x => x.Name == "MainWindow_Loaded");
    var pf = AssemblyDefinition.ReadAssembly(a[2]);
    var pc = AssemblyDefinition.ReadAssembly(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(a[2]), "PresentationCore.dll"));
    var api = AssemblyDefinition.ReadAssembly(System.IO.Path.Combine(a[3], "SourceTree.Api.UI.Wpf.dll"));
    var cc = pf.MainModule.Types.SelectMany(Flat).First(x => x.Name == "ContentControl" && x.Namespace == "System.Windows.Controls");
    var getContentRef = asm.MainModule.ImportReference(cc.Methods.First(x => x.Name == "get_Content"));
    var fe = pf.MainModule.Types.SelectMany(Flat).First(x => x.Name == "FrameworkElement" && x.Namespace == "System.Windows");
    var feRef = asm.MainModule.ImportReference(fe);
    var getDC = asm.MainModule.ImportReference(fe.Methods.First(x => x.Name == "get_DataContext"));
    var setDC = asm.MainModule.ImportReference(fe.Methods.First(x => x.Name == "set_DataContext"));
    var uiElement = pc.MainModule.Types.SelectMany(Flat).First(x => x.Name == "UIElement" && x.Namespace == "System.Windows");
    var uiElementRef = asm.MainModule.ImportReference(uiElement);
    var vth = pc.MainModule.Types.SelectMany(Flat).First(x => x.Name == "VisualTreeHelper");
    var getCountRef = asm.MainModule.ImportReference(vth.Methods.First(x => x.Name == "GetChildrenCount"));
    var getChildRef = asm.MainModule.ImportReference(vth.Methods.First(x => x.Name == "GetChild" && x.Parameters.Count == 2));
    var objGetType = asm.MainModule.ImportReference(typeof(object).GetMethod("GetType"));
    var typeFull = asm.MainModule.ImportReference(typeof(Type).GetProperty("FullName").GetGetMethod());
    var strEq = asm.MainModule.ImportReference(typeof(string).GetMethod("Equals", new[]{typeof(string), typeof(string)}));
    var wlS = asm.MainModule.ImportReference(typeof(Console).GetMethod("WriteLine", new[]{typeof(string)}));
    var wlO = asm.MainModule.ImportReference(typeof(Console).GetMethod("WriteLine", new[]{typeof(object)}));
    var mwVm = asm.MainModule.Types.SelectMany(Flat).First(x => x.Name == "MainWindowViewModel");
    var mwVmRef = asm.MainModule.ImportReference(mwVm);
    var getTabContainer = asm.MainModule.ImportReference(mwVm.Properties.First(x => x.Name == "RepositoryTabContainer").GetMethod);
    var tabIface = api.MainModule.Types.SelectMany(Flat).First(x => x.Name == "IRepositoryTabContainerViewModel");
    var tabIfaceRef = asm.MainModule.ImportReference(tabIface);
    var reopenRef = asm.MainModule.ImportReference(tabIface.Methods.First(x => x.Name == "ReopenTabs"));
    var dv = new TypeDefinition("UiaProbe", "TabFix", TypeAttributes.Public | TypeAttributes.Abstract | TypeAttributes.Sealed, asm.MainModule.TypeSystem.Object);
    asm.MainModule.Types.Add(dv);
    var dF = new FieldDefinition("_d", FieldAttributes.Public | FieldAttributes.Static, asm.MainModule.TypeSystem.Int32);
    dv.Fields.Add(dF);
    var doneF = new FieldDefinition("_done", FieldAttributes.Public | FieldAttributes.Static, asm.MainModule.TypeSystem.Boolean);
    dv.Fields.Add(doneF);
    /* Scan(UIElement, int depth) —— 打印类型 + 计数 */
    var scan = new MethodDefinition("Scan", MethodAttributes.Public | MethodAttributes.Static, asm.MainModule.TypeSystem.Void);
    scan.Parameters.Add(new ParameterDefinition(uiElementRef));
    scan.Parameters.Add(new ParameterDefinition(asm.MainModule.TypeSystem.Int32));
    dv.Methods.Add(scan);
    var sil = scan.Body.GetILProcessor();
    scan.Body.InitLocals = true;
    var vCnt = new VariableDefinition(asm.MainModule.TypeSystem.Int32); scan.Body.Variables.Add(vCnt);
    var sI = new VariableDefinition(asm.MainModule.TypeSystem.Int32); scan.Body.Variables.Add(sI);
    var sCh = new VariableDefinition(uiElementRef); scan.Body.Variables.Add(sCh);
    void SA(Instruction i) => sil.Append(i);
    var sret = sil.Create(OpCodes.Ret);
    var scond = sil.Create(OpCodes.Ldloc, sI);
    var sincr = sil.Create(OpCodes.Ldloc, sI);
    var sbody = sil.Create(OpCodes.Ldarg_0);
    SA(sil.Create(OpCodes.Ldarg_1));
    SA(sil.Create(OpCodes.Ldc_I4, 14));
    SA(sil.Create(OpCodes.Bge, sret));
    SA(sil.Create(OpCodes.Ldarg_0));
    SA(sil.Create(OpCodes.Call, getCountRef));
    SA(sil.Create(OpCodes.Stloc, vCnt));
    SA(sil.Create(OpCodes.Ldc_I4_0));
    SA(sil.Create(OpCodes.Stloc, sI));
    SA(sil.Create(OpCodes.Br, scond));
    SA(sbody);
    SA(sil.Create(OpCodes.Ldloc, sI));
    SA(sil.Create(OpCodes.Call, getChildRef));
    SA(sil.Create(OpCodes.Isinst, uiElementRef));
    SA(sil.Create(OpCodes.Stloc, sCh));
    SA(sil.Create(OpCodes.Ldloc, sCh));
    SA(sil.Create(OpCodes.Brfalse, sincr));
    SA(sil.Create(OpCodes.Ldstr, "  T="));
    SA(sil.Create(OpCodes.Call, wlS));
    SA(sil.Create(OpCodes.Ldloc, sCh));
    SA(sil.Create(OpCodes.Callvirt, objGetType));
    SA(sil.Create(OpCodes.Callvirt, typeFull));
    SA(sil.Create(OpCodes.Call, wlS));
    SA(sil.Create(OpCodes.Ldloc, sCh));
    SA(sil.Create(OpCodes.Ldarg_1));
    SA(sil.Create(OpCodes.Ldc_I4_1));
    SA(sil.Create(OpCodes.Add));
    SA(sil.Create(OpCodes.Call, scan));
    SA(sincr);
    SA(sil.Create(OpCodes.Ldc_I4_1));
    SA(sil.Create(OpCodes.Add));
    SA(sil.Create(OpCodes.Stloc, sI));
    SA(scond);
    SA(sil.Create(OpCodes.Ldloc, vCnt));
    SA(sil.Create(OpCodes.Blt, sbody));
    SA(sret);
    /* Fix(UIElement) —— 递归找 RepoTabPanel 设 DataContext */
    var fix = new MethodDefinition("Fix", MethodAttributes.Public | MethodAttributes.Static, asm.MainModule.TypeSystem.Void);
    fix.Parameters.Add(new ParameterDefinition(uiElementRef));
    fix.Parameters.Add(new ParameterDefinition(tabIfaceRef));
    dv.Methods.Add(fix);
    var il = fix.Body.GetILProcessor();
    fix.Body.InitLocals = true;
    var vCount = new VariableDefinition(asm.MainModule.TypeSystem.Int32); fix.Body.Variables.Add(vCount);
    var vI = new VariableDefinition(asm.MainModule.TypeSystem.Int32); fix.Body.Variables.Add(vI);
    var vChild = new VariableDefinition(uiElementRef); fix.Body.Variables.Add(vChild);
    var vFe = new VariableDefinition(feRef); fix.Body.Variables.Add(vFe);
    void A(Instruction i) => il.Append(i);
    var ret = il.Create(OpCodes.Ret);
    var cond = il.Create(OpCodes.Ldloc, vI);
    var incr = il.Create(OpCodes.Ldloc, vI);
    var body = il.Create(OpCodes.Ldarg_0);
    A(il.Create(OpCodes.Ldsfld, doneF));
    A(il.Create(OpCodes.Brtrue, ret));
    A(il.Create(OpCodes.Ldsfld, dF));
    A(il.Create(OpCodes.Ldc_I4, 12));
    A(il.Create(OpCodes.Bge, ret));
    A(il.Create(OpCodes.Ldsfld, dF));
    A(il.Create(OpCodes.Ldc_I4_1));
    A(il.Create(OpCodes.Add));
    A(il.Create(OpCodes.Stsfld, dF));
    A(il.Create(OpCodes.Ldarg_0));
    A(il.Create(OpCodes.Call, getCountRef));
    A(il.Create(OpCodes.Stloc, vCount));
    A(il.Create(OpCodes.Ldc_I4_0));
    A(il.Create(OpCodes.Stloc, vI));
    A(il.Create(OpCodes.Br, cond));
    A(body);
    A(il.Create(OpCodes.Ldloc, vI));
    A(il.Create(OpCodes.Call, getChildRef));
    A(il.Create(OpCodes.Isinst, uiElementRef));
    A(il.Create(OpCodes.Stloc, vChild));
    A(il.Create(OpCodes.Ldloc, vChild));
    A(il.Create(OpCodes.Brfalse, incr));
    A(il.Create(OpCodes.Ldloc, vChild));
    A(il.Create(OpCodes.Isinst, feRef));
    A(il.Create(OpCodes.Stloc, vFe));
    A(il.Create(OpCodes.Ldloc, vFe));
    A(il.Create(OpCodes.Brfalse, incr));
    A(il.Create(OpCodes.Ldloc, vFe));
    A(il.Create(OpCodes.Callvirt, objGetType));
    A(il.Create(OpCodes.Callvirt, typeFull));
    A(il.Create(OpCodes.Ldstr, "SourceTree.View.Repo.RepoTabPanel"));
    A(il.Create(OpCodes.Call, strEq));
    var notMatch = il.Create(OpCodes.Nop);
    A(il.Create(OpCodes.Brfalse, notMatch));
    A(il.Create(OpCodes.Ldstr, "[TABFIX] match!"));
    A(il.Create(OpCodes.Call, wlS));
    A(il.Create(OpCodes.Ldloc, vFe));
    A(il.Create(OpCodes.Ldarg_1));
    A(il.Create(OpCodes.Callvirt, setDC));
    A(il.Create(OpCodes.Ldstr, "[TABFIX] DataContext set"));
    A(il.Create(OpCodes.Call, wlS));
    A(il.Create(OpCodes.Ldc_I4_1));
    A(il.Create(OpCodes.Stsfld, doneF));
    A(notMatch);
    A(il.Create(OpCodes.Ldloc, vChild));
    A(il.Create(OpCodes.Ldarg_1));
    A(il.Create(OpCodes.Call, fix));
    A(incr);
    A(il.Create(OpCodes.Ldc_I4_1));
    A(il.Create(OpCodes.Add));
    A(il.Create(OpCodes.Stloc, vI));
    A(cond);
    A(il.Create(OpCodes.Ldloc, vCount));
    A(il.Create(OpCodes.Blt, body));
    A(il.Create(OpCodes.Ldsfld, dF));
    A(il.Create(OpCodes.Ldc_I4_1));
    A(il.Create(OpCodes.Sub));
    A(il.Create(OpCodes.Stsfld, dF));
    A(ret);
    /* 入口 */
    var vTabVm = new VariableDefinition(tabIfaceRef); m.Body.Variables.Add(vTabVm);
    m.Body.InitLocals = true;
    var il2 = m.Body.GetILProcessor();
    var first2 = m.Body.Instructions[0];
    void Push(params Instruction[] xs) { foreach (var x in xs) il2.InsertBefore(first2, x); }
    Push(il2.Create(OpCodes.Ldc_I4_0));
    Push(il2.Create(OpCodes.Stsfld, dF));
    Push(il2.Create(OpCodes.Ldc_I4_0));
    Push(il2.Create(OpCodes.Stsfld, doneF));
    Push(il2.Create(OpCodes.Ldstr, "[TABFIX] enter"));
    Push(il2.Create(OpCodes.Call, wlS));
    Push(il2.Create(OpCodes.Ldarg_0));
    Push(il2.Create(OpCodes.Callvirt, getDC));
    Push(il2.Create(OpCodes.Castclass, mwVmRef));
    Push(il2.Create(OpCodes.Callvirt, getTabContainer));
    Push(il2.Create(OpCodes.Stloc, vTabVm));
    Push(il2.Create(OpCodes.Ldarg_0));
    Push(il2.Create(OpCodes.Callvirt, getContentRef));
    Push(il2.Create(OpCodes.Castclass, uiElementRef));
    Push(il2.Create(OpCodes.Ldloc, vTabVm));
    Push(il2.Create(OpCodes.Call, fix));
    Push(il2.Create(OpCodes.Ldsfld, doneF));
    var skipReopen = il2.Create(OpCodes.Nop);
    Push(il2.Create(OpCodes.Brfalse, skipReopen));
    Push(il2.Create(OpCodes.Ldstr, "[TABFIX] reopen..."));
    Push(il2.Create(OpCodes.Call, wlS));
    Push(il2.Create(OpCodes.Ldloc, vTabVm));
    Push(il2.Create(OpCodes.Callvirt, reopenRef));
    Push(il2.Create(OpCodes.Ldstr, "[TABFIX] reopen DONE"));
    Push(il2.Create(OpCodes.Call, wlS));
    /* reopen 后重新扫描（看是否创建了子控件） */
    Push(il2.Create(OpCodes.Ldstr, "[TABFIX] rescan..."));
    Push(il2.Create(OpCodes.Call, wlS));
    Push(il2.Create(OpCodes.Ldarg_0));
    Push(il2.Create(OpCodes.Callvirt, getContentRef));
    Push(il2.Create(OpCodes.Castclass, uiElementRef));
    Push(il2.Create(OpCodes.Ldc_I4_0));
    Push(il2.Create(OpCodes.Call, scan));
    Push(il2.Create(OpCodes.Ldstr, "[TABFIX] rescan DONE"));
    Push(il2.Create(OpCodes.Call, wlS));
    Push(skipReopen);
    asm.Write(a[1]);
    Console.WriteLine("patched -> " + a[1]);
  }
  static System.Collections.Generic.IEnumerable<TypeDefinition> Flat(TypeDefinition t) {
    yield return t;
    foreach (var n in t.NestedTypes) foreach (var x in Flat(n)) yield return x;
  }
}
